<template>
	<view class="second-page">
		<pyh-nv :config="{
			title: '二级页面',
			color: '#000000',
			bgColor: '#ffffff',
		}"></pyh-nv>
		
		<view class="content">
			<view class="info-card">
				<view class="info-title">详细内容</view>
				<view class="info-text">这是二级页面的内容展示区域，用于演示自定义tabbar在页面跳转时的表现。</view>
			</view>
		</view>
	</view>
</template>

<script>
export default {
	data() {
		return {}
	},
	onLoad() {
		// 二级页面不需要显示tabbar
	},
	methods: {
		goBack() {
			uni.navigateBack({
				success: () => {
					// 返回上一页后通知更新 tabbar
					setTimeout(() => {
						uni.$emit('updateTabBar')
					}, 100)
				}
			});
		}
	}
}
</script>

<style>
.second-page {
	display: flex;
	flex-direction: column;
	min-height: 100vh;
	background-color: #f8f8f8;
}

.content {
	margin-top: 0;
	padding: 15px;
}

.banner {
	width: 100%;
	border-radius: 10px;
	margin-bottom: 15px;
}

.info-card {
	background-color: #ffffff;
	border-radius: 10px;
	padding: 15px;
	box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
}

.info-title {
	font-size: 18px;
	font-weight: bold;
	margin-bottom: 10px;
}

.info-text {
	font-size: 16px;
	color: #666;
	line-height: 1.6;
}
</style> 